import Foundation

/// The link of the password reset email, as the app receives it: `lero://reset-password?token=…`.
/// The email points to the backend's bridge page, which hands the token to the app through this scheme.
nonisolated struct PasswordResetLink: Identifiable, Hashable, Sendable {
    static let appScheme = "lero"
    static let appHost = "reset-password"

    let token: String

    var id: String { token }

    /// 32 random bytes in base64url, as generated by the backend.
    private static var tokenPattern: Regex<Substring> { /^[A-Za-z0-9_-]{43}$/ }

    init?(url: URL) {
        guard let components = URLComponents(url: url, resolvingAgainstBaseURL: false),
              components.scheme?.lowercased() == Self.appScheme,
              components.host?.lowercased() == Self.appHost,
              components.path.isEmpty || components.path == "/",
              let token = components.queryItems?.first(where: { $0.name == "token" })?.value,
              token.wholeMatch(of: Self.tokenPattern) != nil
        else { return nil }

        self.token = token
    }
}
